#include <signal.h>
#include <time.h>
#include <ctype.h>

#define VERSION "2.0"
#define DEFAULT_DELAY 4
#define MAX_DELAY 10
#define MIN_DELAY 0

// Global flags
static int async_scroll = 0;
static int bold_chars = 0;
static int all_bold = 0;
