        chars = latin_chars;
        char_set = 0;
    } else {
        chars = latin_chars;
        char_set = 0;
    }

    int width = 80;
    int height = 24;

    /* Get terminal size */
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0) {
        width = ws.ws_col;
        height = ws.ws_row;
    }

    /* Print columns */
    for (int col = 0; col < width; col++) {
        for (int row = 0; row < height; row++) {
            int idx = (row * width + col) % (strlen(chars) * width);
            printf("%c", chars[idx % strlen(chars)]);
        }
        printf("\n");
    }
}

/* Print message in center */
void print_message(const char *message) {
    int width = 80;
    int height = 24;

    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0) {
        width = ws.ws_col;
        height = ws.ws_row;
    }

    /* Clear screen */
    printf("\033[2J\033[H");

    /* Center the message */
    int msg_len = strlen(message);
    int start_col = (width - msg_len) / 2;

    for (int col = 0; col < width; col++) {
        if (col < start_col || col >= start_col + msg_len) {
            printf(" ");
        } else {
            printf("%c", message[col - start_col]);
        }
    }
    printf("\n");
}
